String str(CursorController_PixelCursor v) { switch (v) {
  case CursorController_PixelCursor::NORMAL: return S("NORMAL");
  case CursorController_PixelCursor::ACTIVE: return S("ACTIVE");
  case CursorController_PixelCursor::BUSY: return S("BUSY");
  case CursorController_PixelCursor::TALK: return S("TALK");
  case CursorController_PixelCursor::INSPECT: return S("INSPECT");
  case CursorController_PixelCursor::OK: return S("OK");
  case CursorController_PixelCursor::TRANSITION: return S("TRANSITION");
  default: return str((int)v); } }
